const fs = require('fs');
const path = require('path');
const { withAndroidManifest, withDangerousMod, AndroidConfig } = require('expo/config-plugins');

// "Quick note" in the menu that opens when the app icon is pressed and held (an Android static shortcut, like the
// PWA's shortcut on the web). It opens `noteriv://quick`, which expo-router maps to app/quick.tsx. The label
// follows the phone's language (values/ and values-vi/). android/ is regenerated by `expo prebuild`, so this
// plugin writes the files on every prebuild.

const SHORTCUTS_XML = `<?xml version="1.0" encoding="utf-8"?>
<shortcuts xmlns:android="http://schemas.android.com/apk/res/android">
  <shortcut
    android:shortcutId="quick-note"
    android:enabled="true"
    android:icon="@mipmap/ic_launcher"
    android:shortcutShortLabel="@string/shortcut_quick_note"
    android:shortcutLongLabel="@string/shortcut_quick_note">
    <intent
      android:action="android.intent.action.VIEW"
      android:data="noteriv://quick" />
  </shortcut>
</shortcuts>
`;

const LABELS = { values: 'Quick note', 'values-vi': 'Ghi nhanh' };

function withShortcutFiles(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const res = path.join(config.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res');
      fs.mkdirSync(path.join(res, 'xml'), { recursive: true });
      fs.writeFileSync(path.join(res, 'xml', 'shortcuts.xml'), SHORTCUTS_XML);
      for (const [dir, label] of Object.entries(LABELS)) {
        fs.mkdirSync(path.join(res, dir), { recursive: true });
        fs.writeFileSync(
          path.join(res, dir, 'shortcuts_strings.xml'),
          `<?xml version="1.0" encoding="utf-8"?>\n<resources>\n  <string name="shortcut_quick_note">${label}</string>\n</resources>\n`
        );
      }
      return config;
    },
  ]);
}

function withShortcutMetaData(config) {
  return withAndroidManifest(config, (config) => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(config.modResults);
    const meta = (activity['meta-data'] ??= []);
    if (!meta.some((m) => m.$['android:name'] === 'android.app.shortcuts')) {
      meta.push({ $: { 'android:name': 'android.app.shortcuts', 'android:resource': '@xml/shortcuts' } });
    }
    return config;
  });
}

module.exports = function withQuickNoteShortcut(config) {
  return withShortcutMetaData(withShortcutFiles(config));
};
